import{a as e,n as t,o as n,r,s as i,t as a}from"./app-CFD1XTs1.js";import{t as o}from"./plugin-vue_export-helper-BDNMzG2s.js";var s=JSON.parse(`{"path":"/pentest/dnshajack/","title":"DNS 劫持","lang":"zh-CN","frontmatter":{"description":"DNS 劫持 DNS 劫持（DNS Hijacking）是一种网络攻击手段，攻击者通过篡改或操控域名系统（DNS）的解析过程，将用户的 DNS 请求指向恶意的或不正确的 IP 地址，从而干扰用户访问正常网站或将用户流量引导到恶意网站。 DNS 劫持的常见类型： 1. 本地 DNS 劫持： 攻击者通过感染用户计算机或网络中的路由器，篡改其 DNS 设置。...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"DNS 劫持\\",\\"image\\":[\\"\\"],\\"dateModified\\":\\"2026-03-11T05:49:26.000Z\\",\\"author\\":[{\\"@type\\":\\"Person\\",\\"name\\":\\"DeeLMind\\",\\"url\\":\\"https://deelmind.com\\"}]}"],["meta",{"property":"og:url","content":"https://deelmind.com/pentest/dnshajack/"}],["meta",{"property":"og:site_name","content":"極客方舟"}],["meta",{"property":"og:title","content":"DNS 劫持"}],["meta",{"property":"og:description","content":"DNS 劫持 DNS 劫持（DNS Hijacking）是一种网络攻击手段，攻击者通过篡改或操控域名系统（DNS）的解析过程，将用户的 DNS 请求指向恶意的或不正确的 IP 地址，从而干扰用户访问正常网站或将用户流量引导到恶意网站。 DNS 劫持的常见类型： 1. 本地 DNS 劫持： 攻击者通过感染用户计算机或网络中的路由器，篡改其 DNS 设置。..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-03-11T05:49:26.000Z"}],["meta",{"property":"article:modified_time","content":"2026-03-11T05:49:26.000Z"}]]},"git":{"createdTime":1735651697000,"updatedTime":1773208166000,"contributors":[{"name":"DeeLMind","username":"DeeLMind","email":"deelmind@gmail.com","commits":2,"url":"https://github.com/DeeLMind"}]},"readingTime":{"minutes":2.37,"words":711},"filePathRelative":"pentest/dnshajack/README.md","autoDesc":true}`),c={name:`README.md`};function l(o,s,c,l,u,d){let f=i(`DocsAD`);return n(),t(`div`,null,[s[0]||=a(`h1`,{id:`dns-劫持`,tabindex:`-1`},[a(`a`,{class:`header-anchor`,href:`#dns-劫持`},[a(`span`,null,`DNS 劫持`)])],-1),s[1]||=a(`p`,null,`DNS 劫持（DNS Hijacking）是一种网络攻击手段，攻击者通过篡改或操控域名系统（DNS）的解析过程，将用户的 DNS 请求指向恶意的或不正确的 IP 地址，从而干扰用户访问正常网站或将用户流量引导到恶意网站。`,-1),e(f),s[2]||=r(`<h2 id="dns-劫持的常见类型" tabindex="-1"><a class="header-anchor" href="#dns-劫持的常见类型"><span>DNS 劫持的常见类型：</span></a></h2><h3 id="_1-本地-dns-劫持" tabindex="-1"><a class="header-anchor" href="#_1-本地-dns-劫持"><span>1. 本地 DNS 劫持：</span></a></h3><ul><li>攻击者通过感染用户计算机或网络中的路由器，篡改其 DNS 设置。用户的 DNS 请求会被引导到攻击者控制的 DNS 服务器，从而得到错误的域名解析结果。</li><li>例如，用户输入一个网址，但被引导到一个恶意网站，可能用于钓鱼攻击或传播恶意软件。</li></ul><h3 id="_2-isp-级-dns-劫持" tabindex="-1"><a class="header-anchor" href="#_2-isp-级-dns-劫持"><span>2. ISP 级 DNS 劫持：</span></a></h3><ul><li>攻击者可能通过入侵互联网服务提供商（ISP）的 DNS 服务器，篡改 DNS 响应，使所有通过该 ISP 访问互联网的用户都受到影响。</li><li>这种情况通常由恶意 ISP 或黑客执行，用户无论访问什么网站，都可能被重定向到一个假网站。</li></ul><h3 id="_3-中间人攻击-man-in-the-middle-mitm" tabindex="-1"><a class="header-anchor" href="#_3-中间人攻击-man-in-the-middle-mitm"><span>3. 中间人攻击（Man-in-the-Middle，MITM）：</span></a></h3><ul><li>攻击者通过截获 DNS 请求和响应，在两者之间注入恶意代码或篡改 DNS 数据，导致用户访问的是恶意网站。</li></ul><h2 id="dns-劫持的危害" tabindex="-1"><a class="header-anchor" href="#dns-劫持的危害"><span>DNS 劫持的危害：</span></a></h2><ol><li><strong>恶意网站重定向：</strong> 用户访问的合法网站被重定向到攻击者设定的恶意网站，可能窃取个人信息、账号密码或财务信息。</li><li><strong>钓鱼攻击：</strong> 攻击者将用户引导到伪造的网站，诱使用户输入敏感数据（如银行账户、社交安全号码等）。</li><li><strong>广告劫持：</strong> 将用户流量定向到包含广告的恶意网页或劫持用户的搜索查询，强制显示不需要的广告。</li><li><strong>隐私泄露：</strong> 攻击者可利用劫持的 DNS 数据来监控用户的上网行为、搜集敏感信息，甚至传播恶意软件。</li></ol><h2 id="防范措施" tabindex="-1"><a class="header-anchor" href="#防范措施"><span>防范措施：</span></a></h2><ol><li><strong>使用安全的 DNS 服务：</strong><ul><li>例如，使用 Google DNS（8.8.8.8）、Cloudflare DNS（1.1.1.1）等可靠的公共 DNS 服务，避免使用 ISP 提供的默认 DNS。</li></ul></li><li><strong>启用 DNSSEC（DNS 安全扩展）：</strong><ul><li>DNSSEC 能够确保 DNS 响应未被篡改，提供更高的安全性。</li></ul></li><li><strong>定期更新路由器固件：</strong><ul><li>改善网络设备的安全性，防止恶意软件感染。</li></ul></li><li><strong>使用 HTTPS：</strong><ul><li>确保所有网站都启用了 HTTPS 协议，加密传输数据，避免中间人攻击。</li></ul></li><li><strong>使用 VPN：</strong><ul><li>使用 VPN 可以有效加密网络流量，避免 DNS 劫持通过本地网络的攻击。</li></ul></li></ol><p>通过这些防范措施，可以大大降低遭遇 DNS 劫持的风险，保护个人隐私和数据安全。</p>`,12)])}var u=o(c,[[`render`,l]]);export{s as _pageData,u as default};